// Group Name: ungrouped
// Rule ID: 112148
// Level: 10
// If SID: 61615
// Rule Groups: sysmon_event_13,
// Options: no_full_log
// MITRE ATT&CK: T1564.002
// Description:
// Suspicious registry modification detected: Hiding user accounts via Userlist key (T1564.002 - Hidden Users)

<rule id="112148" level="10">
